<script setup lang="ts">
import {useParameterTransaction} from './useParameterTransaction';
import ParameterDialog from './ParameterDialog.vue';
const settingsOpen=ref(false);const settingsTab=ref('恢复分区');
defineExpose({openSettings:()=>settingsOpen.value=true});
import {ref,computed,watch,onBeforeUnmount} from 'vue';import {apiError} from './apiError';
const props=defineProps<{projectId:string;section:string}>();
const project=ref<any>(null),engineering=ref<any>(null),network=ref<any>(null),jobs=ref<any[]>([]),job=ref<any>(null);
const error=ref(''),busy=ref(false),name=ref('黑启动恢复操作规划'),mode=ref('parallel');
const minutes=ref(5),steps=ref(12),crews=ref(1),operationMinutes=ref(1),evaluations=ref(200),wall=ref(600);
const closed=ref<number[]>([]),manualSources=ref<string[]>([]),manualSwitches=ref<string[]>([]),manualLoads=ref<string[]>([]);
const advanced=ref(JSON.stringify({resource_terminals:{},load_terminals:{},backup_powered_devices:[],line_ready_step:{},equipment_ready_step:{},synchronization:[],energizing_current_limits_a:{},transient_parameter_provenance:'',require_inrush_parameters:false},null,2));
const time=ref(0);let generation=0,timer:ReturnType<typeof setTimeout>|undefined;
const terminal=new Set(['succeeded','incomplete','failed','cancelled','interrupted']);
const names:Record<string,string>={queued:'排队',running:'计算中',cancel_requested:'等待取消',succeeded:'模型计算结束',incomplete:'搜索未完整结束',failed:'失败',cancelled:'已取消',interrupted:'中断',passed:'模型内通过',not_checked:'未校核',not_applicable:'不适用',external_passed:'外部输入数值通过',start:'启动资源',close:'线路合闸',pickup:'投入负荷'};
const result=computed(()=>job.value?.result),activeJob=computed(()=>job.value&&!terminal.has(job.value.status));
const inventory=computed(()=>engineering.value?.inventory);
const resources=computed(()=>[...(inventory.value?.sources||[]),...(inventory.value?.storage||[])].filter((a:any)=>a.existing));
const switches=computed(()=>(inventory.value?.switches||[]).filter((a:any)=>a.existing));
const loads=computed(()=>(inventory.value?.loads||[]).filter((a:any)=>a.existing));
const frozenNetwork=computed(()=>job.value?.input?.network||network.value);
const snapshot=computed(()=>result.value?.dispatch.rows[time.value]);
const positions=computed(()=>{const n=frozenNetwork.value;if(!n)return {};const depth:Record<number,number>={1:0},count:Record<number,number>={},p:Record<number,{x:number;y:number}>={};const queue=[1];for(const id of queue)for(const e of n.lines.filter((a:any)=>a.status)){const other=e.from_node===id?e.to_node:e.to_node===id?e.from_node:null;if(other!==null&&depth[other]===undefined){depth[other]=depth[id]+1;queue.push(other)}}for(const node of n.nodes){const d=depth[node.node]||0;p[node.node]={x:55+d*110,y:45+(count[d]||0)*75};count[d]=(count[d]||0)+1}return p});
const box=computed(()=>{const p=Object.values(positions.value);return `0 0 ${Math.max(600,...p.map(v=>v.x+55))} ${Math.max(230,...p.map(v=>v.y+45))}`});
const nodeLive=(id:number)=>snapshot.value?.nodes.some((n:any)=>n.node===id&&n.energized);
const lineLive=(id:number)=>snapshot.value?.lines.some((n:any)=>n.line===id&&n.closed);
async function api(url:string,options?:RequestInit){const r=await fetch(url,options);const d=await r.json();if(!r.ok)throw Error(apiError(d.detail));return d}
async function refresh(){const g=++generation;clearTimeout(timer);job.value=null;jobs.value=[];project.value=null;engineering.value=null;network.value=null;manualSources.value=[];manualSwitches.value=[];manualLoads.value=[];closed.value=[];busy.value=false;error.value='';if(!props.projectId)return;try{const[p,e,h]=await Promise.all([api('/api/projects/'+props.projectId),api('/api/engineering/projects/'+props.projectId),api('/api/study-jobs?project_id='+props.projectId)]);const n=p.state.network||await api('/api/network/case33');if(g!==generation)return;project.value=p;engineering.value=e;network.value=n;jobs.value=h.filter((j:any)=>j.module==='restoration');closed.value=n.lines.filter((l:any)=>l.status&&!e.inventory.switches.some((s:any)=>s.existing&&s.line_id===l.line)).map((l:any)=>l.line);if(jobs.value.length)await inspect(jobs.value[0].id)}catch(e){if(g===generation)error.value=String(e)}}
async function inspect(id:string){clearTimeout(timer);const g=generation;try{const d=await api('/api/study-jobs/'+id+'?include_input=true&include_result=true');if(g!==generation||d.project_id!==props.projectId)return;job.value=d;time.value=0;if(!terminal.has(d.status))timer=setTimeout(()=>poll(id,g),500)}catch(e){if(g===generation)error.value=String(e)}}
async function poll(id:string,g:number){if(g!==generation)return;try{const d=await api('/api/study-jobs/'+id);if(g!==generation||job.value?.id!==id)return;if(terminal.has(d.status)){const full=await api('/api/study-jobs/'+id+'?include_input=true&include_result=true');if(g!==generation||job.value?.id!==id)return;job.value=full;time.value=0;const h=await api('/api/study-jobs?project_id='+props.projectId);if(g===generation)jobs.value=h.filter((j:any)=>j.module==='restoration')}else{job.value=d;timer=setTimeout(()=>poll(id,g),1000)}}catch(e){if(g===generation){error.value=String(e);timer=setTimeout(()=>poll(id,g),3000)}}}
async function submit(){commitSettings(false);const g=generation;busy.value=true;error.value='';try{if(!project.value||!engineering.value?.revision)throw Error('请先保存工程与设备台账');const extra=JSON.parse(advanced.value);if(!extra||Array.isArray(extra)||typeof extra!=='object')throw Error('高级参数须为JSON对象');const {base:baseExtra={},...settings}=extra;
 const base={...baseExtra,project_id:props.projectId,project_revision:project.value.revision,engineering_revision:engineering.value.revision,steps:steps.value,step_hours:minutes.value/60,grid_available_kw:[0],time_limit_seconds:baseExtra.time_limit_seconds||30};
 const parameters={...settings,base,name:name.value,mode:mode.value,initial_closed_lines:closed.value,manual_resource_ids:manualSources.value,manual_switch_ids:manualSwitches.value,manual_load_ids:manualLoads.value,manual_crews:crews.value,manual_operation_minutes:operationMinutes.value,maximum_evaluations:evaluations.value,wall_time_seconds:wall.value};
 const d=await api('/api/study-jobs',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({module:'restoration',parameters})});if(g!==generation)return;job.value=d;jobs.value=[d,...jobs.value];timer=setTimeout(()=>poll(d.id,g),200)}catch(e){if(g===generation)error.value=String(e)}finally{if(g===generation)busy.value=false}}
async function action(type:string){const g=generation,id=job.value?.id;if(!id)return;try{const d=await api('/api/study-jobs/'+id+'/'+type,{method:'POST'});if(g===generation){job.value=d;clearTimeout(timer);timer=setTimeout(()=>poll(d.id,g),200)}}catch(e){if(g===generation)error.value=String(e)}}
watch(()=>props.projectId,refresh,{immediate:true});onBeforeUnmount(()=>{++generation;clearTimeout(timer)});
const fmt=(n:any,d=3)=>typeof n==='number'?n.toFixed(d):'—';
const commitSettings=useParameterTransaction(settingsOpen,{name,mode,minutes,steps,crews,operationMinutes,evaluations,wall,closed,manualSources,manualLoads,manualSwitches,advanced});
</script>
<template>
<article><h3>恢复规划参数</h3><p>参数集中编辑，任务和结果沿用冻结输入。编辑后在弹窗内明确提交。</p><button class="settings-trigger" @click="settingsOpen=true">恢复规划参数</button></article><ParameterDialog transactional @apply="commitSettings()" v-model:open="settingsOpen" title="恢复规划参数" :tabs="['恢复分区','启动资源','一二次约束']" v-model:active="settingsTab"><article><h3>黑启动路径优化 · {{section}}</h3><p>从全停电状态，按负荷重要度、电气路径和可用资源规划启动、合闸、负荷投入。保留的每个操作前缀都经过全时域逐设备MILP复算；本页输出工程研究预案，动态稳定和保护未校核，不产生安全执行许可。</p><p v-if="error" class="error">{{error}}</p>
<div class="actions"><button @click="refresh" :disabled="busy">重新读取输入与任务</button><span>工程版本 {{project?.revision||'—'}} / 台账版本 {{engineering?.revision||0}}</span></div>
<template v-if="settingsTab==='恢复分区'"><div class="fields"><label>任务名称<input v-model="name"></label><label>恢复方式<select v-model="mode"><option value="parallel">独立分区并行</option><option value="serial">全部串行</option></select></label><label>时间步 / min<select v-model.number="minutes"><option :value="1">1</option><option :value="5">5</option><option :value="15">15</option><option :value="30">30</option><option :value="60">60</option></select></label><label>计算步数<input type="number" v-model.number="steps" min="1" max="672"></label><label>人工队伍数量<input type="number" v-model.number="crews" min="1" max="16"></label><label>资源/负荷人工操作时间 min<input type="number" v-model.number="operationMinutes" min=".01"></label><label>调度评估次数上限<input type="number" v-model.number="evaluations" min="1" max="1000"></label><label>总时限 s<input type="number" v-model.number="wall" min="1" max="3600"></label></div>
<h4>灾后初始闭合线路</h4><p>初始全停电不等于所有开关断开。未声明独立控制的负荷将随所在分区带电全量投入；无开关的线路无法在序列中自动合闸。已损坏设备须给出修复步。</p><div class="checks"><label v-for="l in network?.lines" :key="l.line"><input type="checkbox" :value="l.line" v-model="closed">线路 {{l.line}} · {{l.from_node}}—{{l.to_node}}</label></div></template>
<template v-if="settingsTab==='启动资源'"><h4>资源启动操作</h4><p>勾选表示本次研究允许人工启动该资源；遥控方式在“一二次约束”配置同节点终端、控制范围、路由与备用供电。非黑启动资源须先有已带电分区。台账曲线需为单值或与计算步数一致，不自动重采样。</p><div class="scroll"><table><tr><th>允许人工启动</th><th>编号/名称</th><th>节点</th><th>功率 kW</th><th>构网/黑启动</th><th>启动/到位 min</th><th>燃料或储能</th></tr><tr v-for="r in resources" :key="r.id"><td><label><input type="checkbox" :value="r.id" v-model="manualSources">人工启动 {{r.id}}</label></td><td>{{r.id}} / {{r.name}}</td><td>{{r.node}}</td><td>{{r.rated_kw??r.power_kw}}</td><td>{{r.grid_forming?'是':'否'}} / {{r.black_start?'是':'否'}}</td><td>{{r.startup_minutes||0}} / {{r.arrival_minutes}}</td><td>{{r.energy_kwh!=null?r.energy_kwh+' kWh储能':r.fuel_kwh!=null?r.fuel_kwh+' kWh可发电量':'按台账曲线/时长'}}</td></tr></table></div>
<h4>可独立投入的负荷</h4><p>只勾选有独立接入控制和人工操作条件的负荷；未勾选且未映射遥控终端的负荷随分区带电投入，不会为了得到可行预案而自动切掉。</p><div class="checks"><label v-for="l in loads" :key="l.id"><input type="checkbox" :value="l.id" v-model="manualLoads">独立人工投入 {{l.id}} · {{l.name}}</label></div></template>
<template v-if="settingsTab==='一二次约束'"><h4>开关操作方式</h4><p>勾选人工操作后使用人工队伍；否则仅台账已配置的遥控开关可按实际终端/控制器路由操作，失联不会自动转人工。控制器与终端须有站用电或显式备用电源。</p><div class="checks"><label v-for="s in switches" :key="s.id"><input type="checkbox" :value="s.id" v-model="manualSwitches">人工操作 {{s.id}} · 线路{{s.line_id}} · 台账{{s.remote_control?'可遥控':'非遥控'}}</label></div>
<h4>高级约束与外部校核数据 JSON</h4><p>resource_terminals/load_terminals映射资源或负荷ID到终端ID；backup_powered_devices声明备用供电的控制器/终端。line_ready_step、equipment_ready_step以0为起点。带电合区需synchronization提供有效步窗和电压/频率/相角差及来源；外部数值不视为独立动态认证。短时电流参数仅用于励磁容量包络筛查。</p><textarea v-model="advanced" rows="18" spellcheck="false"></textarea><p>高级base可设置基准可用率、曲线时间、单次调度时限等；页面总步数/时间步及全停电条件优先。source_commitment、required_energized_nodes、line_status与带电负荷约束由操作序列生成。</p></template>
<button v-if="settingsTab!=='恢复序列'" class="primary" @click="submit" :disabled="busy||!engineering?.revision">{{busy?'正在冻结输入…':'提交黑启动恢复规划'}}</button>
</article></ParameterDialog>
<article v-if="job"><h3>恢复任务 · {{names[job.status]||job.status}}</h3><p>{{job.name}} · {{job.id}} · 输入摘要 {{job.input_sha256}}</p><p v-if="job.input">冻结参数：{{job.input.parameters.mode==='parallel'?'分区并行':'串行'}} / {{fmt(job.input.parameters.base.step_hours*60,0)}} min × {{job.input.parameters.base.steps}}步 / 人工队伍{{job.input.parameters.manual_crews}}。</p><progress :value="job.progress?.fraction||0" max="1"></progress><p>已评估 {{job.progress?.evaluations||0}} 个候选 · {{job.progress?.phase}}</p><p v-if="job.error" class="error">{{job.error}}</p><div class="actions"><button v-if="activeJob" @click="action('cancel')" :disabled="job.status==='cancel_requested'">请求取消</button><button v-else @click="action('retry')">冻结输入新建重试</button><a :href="'/api/study-jobs/'+job.id+'/download'">完整输入与预案 JSON</a><a v-if="result" :href="'/api/study-jobs/'+job.id+'/csv'">操作序列 CSV</a><a :href="'/api/study-jobs/'+job.id+'/log'" target="_blank">工作日志</a></div>
<template v-if="result"><p>操作 {{result.actions.length}} 步 · 电气带电分区 {{result.partitions.length}} 个 · 评估 {{result.evaluations}} 次 · {{fmt(result.runtime_seconds,2)}} s。{{result.goal_status==='restored_to_horizon'?'参与负荷已在本时域内恢复全量供电。':result.goal_status==='partially_restored'?'负荷仅部分恢复。':'未找到负荷恢复预案。'}}{{result.status==='incomplete_search'?'搜索达到预算，结果不完整。':''}}</p><p class="notice">执行状态：未获安全执行许可。下方“模型内通过”仅针对已计算约束；动态稳定、实际同步、励磁波形及保护等未校核项仍须补齐。</p>
<template v-if="section==='恢复分区'"><h4>重要度排序与电气距离预分配</h4><p>预分配先考虑容量和电气距离，属于搜索参考；最终资源与分区以全时域调度复算为准，不用初始匹配替代可行性证明。</p><div class="scroll"><table><tr><th>负荷/类别</th><th>优先级</th><th>匹配种子</th><th>距离 Ω</th><th>路径线路</th><th>初始容量匹配</th></tr><tr v-for="r in result.preallocation"><td>{{r.load_id}} / {{r.class}}</td><td>{{r.priority}}</td><td>{{r.seed_id||'无可用种子'}}</td><td>{{fmt(r.distance_ohm)}}</td><td>{{r.path_lines.join(', ')}}</td><td>{{r.capacity_match?'是':'否/无候选'}}</td></tr></table></div>
<h4>最终带电分区</h4><div class="scroll"><table><tr><th>分区</th><th>节点</th><th>投入资源</th><th>负荷</th><th>首次带电 min</th></tr><tr v-for="p in result.partitions"><td>{{p.id}}</td><td>{{p.nodes.join(', ')}}</td><td>{{p.resources.join(', ')}}</td><td>{{p.loads.join(', ')}}</td><td>{{fmt(p.first_energized_minutes,1)}}</td></tr></table></div></template>
<h4 v-if="section==='一二次约束'">约束校核状态</h4><div v-if="section==='一二次约束'" class="scroll"><table><tr><th>约束</th><th>状态</th></tr><tr v-for="c in result.checks"><td>{{c.name}}</td><td>{{names[c.status]||c.status}}</td></tr></table></div>
<h4>带时间操作序列</h4><div class="scroll"><table><tr><th>操作</th><th>对象</th><th>开始/完成 min</th><th>操作方式/路径</th><th>新增带电节点</th><th>励磁包络</th><th>预同步</th></tr><tr v-for="a in result.actions"><td>{{names[a.kind]}}</td><td>{{a.target_id}} · {{a.target_name}}</td><td>{{fmt(a.start_minutes,1)}} / {{fmt(a.end_minutes,1)}}</td><td>{{a.control.mode==='manual'?'人工队伍 '+a.control.crew:a.control.route.join(' → ')+' · '+a.control.latency_ms+'ms'}}</td><td>{{a.new_energized_nodes.join(', ')}}</td><td>{{names[a.inrush_screen.status]||a.inrush_screen.status}}</td><td>{{a.synchronization?names[a.synchronization.status]:'不涉及带电合区'}}</td></tr></table></div>
<h4>恢复回放</h4><label>查看时刻<select v-model.number="time"><option v-for="(r,i) in result.dispatch.rows" :value="i">{{i}} · {{r.timestamp}}</option></select></label><p v-if="snapshot">负荷 {{fmt(snapshot.load_kw)}} kW / 供电 {{fmt(snapshot.served_kw)}} kW / 未供 {{fmt(snapshot.total_unsupplied_kw)}} kW。示意布局，非地理坐标；灰色为未带电，虚线为未闭合。</p>
<div v-if="snapshot&&frozenNetwork" class="topology"><svg :viewBox="box" role="img" aria-label="黑启动恢复时刻拓扑"><g v-for="l in frozenNetwork.lines" :key="l.line"><line :x1="positions[l.from_node]?.x" :y1="positions[l.from_node]?.y" :x2="positions[l.to_node]?.x" :y2="positions[l.to_node]?.y" :stroke="lineLive(l.line)?'#087b7b':'#a7b5b8'" :stroke-dasharray="lineLive(l.line)?undefined:'6 5'" stroke-width="3"/><text :x="(positions[l.from_node].x+positions[l.to_node].x)/2" :y="(positions[l.from_node].y+positions[l.to_node].y)/2-8" text-anchor="middle" font-size="12">线路{{l.line}}</text></g><g v-for="n in frozenNetwork.nodes" :key="n.node"><circle :cx="positions[n.node].x" :cy="positions[n.node].y" r="17" :fill="nodeLive(n.node)?'#087b7b':'#d8dfe0'"/><text :x="positions[n.node].x" :y="positions[n.node].y+4" text-anchor="middle" :fill="nodeLive(n.node)?'white':'#40585b'" font-size="12">{{n.node}}</text></g></svg></div>
<div class="scroll"><table><tr><th>负荷</th><th>类别</th><th>持续全量供电起点 min</th><th>恢复至时域末</th></tr><tr v-for="l in result.load_recovery"><td>{{l.load_id}}</td><td>{{l.class}}</td><td>{{fmt(l.first_sustained_full_supply_minutes,1)}}</td><td>{{l.restored_to_horizon?'是':'否'}}</td></tr></table></div>
<details><summary>失败候选与模型边界</summary><p v-for="s in result.scope">{{s}}</p><pre>{{JSON.stringify(result.rejected_candidates,null,2)}}</pre></details>
</template></article>
<article><h3>本工程恢复规划档案</h3><p v-if="!jobs.length">尚无恢复任务。</p><button class="record" v-for="j in jobs" :key="j.id" @click="inspect(j.id)">{{j.name}} · {{names[j.status]||j.status}} · {{new Date(j.created*1000).toLocaleString()}}</button></article>
</template>
<style scoped>.fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;margin:20px 0}.fields label{display:flex;justify-content:space-between;align-items:center;gap:12px}.fields input,.fields select{width:210px}input,select{padding:8px;border:1px solid #c8dcdf;max-width:100%}.checks{display:flex;flex-wrap:wrap;gap:18px;margin:20px 0}.checks label{display:flex;align-items:center;gap:8px}.scroll{overflow:auto;max-height:420px;margin:20px 0}td,th{white-space:nowrap}.actions{display:flex;flex-wrap:wrap;gap:16px;align-items:center;margin:18px 0}.primary{margin:22px 0}.record{display:block;margin:12px 0}textarea{width:100%;box-sizing:border-box;font-family:monospace}.topology{overflow:auto;background:#f8fbfb;margin:16px 0}.topology svg{min-width:600px;width:100%;max-height:420px}progress{width:100%;height:18px}pre{max-height:350px;overflow:auto}details{margin:20px 0}@media(max-width:1050px){.fields{grid-template-columns:1fr}}</style>
